const sumRegistryLayersByKind = `-- name: SumRegistryLayersByKind :many
SELECT charged_to, sum(size_bytes) AS bytes FROM registry_layers GROUP BY charged_to
`

type SumRegistryLayersByKindRow struct {
	ChargedTo string
	Bytes     sql.NullFloat64
}

func (q *Queries) SumRegistryLayersByKind(ctx context.Context) ([]SumRegistryLayersByKindRow, error) {
	rows, err := q.query(ctx, q.sumRegistryLayersByKindStmt, sumRegistryLayersByKind)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SumRegistryLayersByKindRow
	for rows.Next() {
		var i SumRegistryLayersByKindRow
		if err := rows.Scan(&i.ChargedTo, &i.Bytes); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

